{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Selegiline, a lipophilic basic tertiary amine, has an absolute oral bioavailability of 4.0% after a 10 mg oral dose in healthy volunteers compared with IV, demonstrating extensive first-pass extraction; this high-transfer analogue supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Rotigotine, an aminotetralin with a lipophilic N-alkyl/aryl amine motif, has low oral bioavailability in humans and is restricted to non-oral routes; this high-transfer analogue supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Selegiline oral tablet absolute bioavailability was 4.3% in healthy volunteers versus IV infusion, reinforcing the low-F pattern for lipophilic tertiary amines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Amitriptyline, a tricyclic tertiary amine with a dimethylaminopropylidene side chain, has a weighted mean oral bioavailability of 45% in humans, providing moderate-transfer contradictory evidence for higher F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C47"],
      "claim": "Alfentanil, an N-phenylpiperidine amide, has baseline oral bioavailability of 37% in healthy volunteers, providing moderate-transfer contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Amiodarone, a lipophilic diethylamino-substituted aromatic drug, has absolute oral bioavailability of 65% (range 29-100%), providing lower-transfer contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) based on high-transfer analogues selegiline and rotigotine showing 4-10% or low F due to extensive first-pass metabolism; moderate-transfer high-F analogues (amitriptyline, alfentanil, amiodarone) are outweighed by the higher transferability and consistency of the low-F evidence.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "First-pass metabolic stability of the diethylaminopropyl aniline/indane scaffold is not directly measured.",
    "Formulation-dependent absorption and possible transporter/efflux effects are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

